clear all; close all; clc;% --- Constants ---C = 1.35;beta = 4.0;alpha = [-0.024, 0.0216, -0.0012, 0.12];dt = 0.01;              % 5 mst_end = 300;t = 0:dt:t_end;n_steps = length(t);HR_bpm = 95;Gamma_t = 0.08804 * HR_bpm - 0.06754;H_values = [3.0, 2.729, 2.164];titles = {'Normal Rhythm', 'Quasiperiodicity', 'VF'};figure('Name', 'Fixed-Step Tustin Implicit Solver (dt=0.005)');for h_idx = 1:3    H = H_values(h_idx);    % Initialize States    x = zeros(4, n_steps);    x(:,1) = [0.0; 0.0; 0.1; 0.0];   % Initial condition    % --- Main Simulation Loop ---    for n = 1:n_steps-1        xp = x(:, n);   % previous state        xn = xp;        % initial guess for x_{n+1}        % --- Newton-Raphson loop ---        for iter = 1:10            f_n = Gamma_t * [ ...                xn(1) - xn(2) - C*xn(1)*xn(2) - xn(1)*xn(2)^2;                H*xn(1) - 3*xn(2) + C*xn(1)*xn(2) + xn(1)*xn(2)^2 + beta*(xn(4) - xn(2));                xn(3) - xn(4) - C*xn(3)*xn(4) - xn(3)*xn(4)^2;                H*xn(3) - 3*xn(4) + C*xn(3)*xn(4) + xn(3)*xn(4)^2 + 2*beta*(xn(2) - xn(4))];            f_p = Gamma_t * [ ...                xp(1) - xp(2) - C*xp(1)*xp(2) - xp(1)*xp(2)^2;                H*xp(1) - 3*xp(2) + C*xp(1)*xp(2) + xp(1)*xp(2)^2 + beta*(xp(4) - xp(2));                xp(3) - xp(4) - C*xp(3)*xp(4) - xp(3)*xp(4)^2;                H*xp(3) - 3*xp(4) + C*xp(3)*xp(4) + xp(3)*xp(4)^2 + 2*beta*(xp(2) - xp(4))];            % Tustin residual            R = xn - xp - (dt/2) * (f_n + f_p);            % Jacobian of residual wrt xn            J = eye(4) - (dt/2) * Gamma_t * [ ...                (1 - C*xn(2) - xn(2)^2),           (-1 - C*xn(1) - 2*xn(1)*xn(2)), 0, 0;                (H + C*xn(2) + xn(2)^2),           (-3 + C*xn(1) + 2*xn(1)*xn(2) - beta), 0, beta;                0,                                  0, (1 - C*xn(4) - xn(4)^2), (-1 - C*xn(3) - 2*xn(3)*xn(4));                0,                             2*beta, (H + C*xn(4) + xn(4)^2), (-3 + C*xn(3) + 2*xn(3)*xn(4) - 2*beta)];            % Newton step            dx = J \ R;            lambda = 0.5;   % try 0.5 if Newton is too aggressive            xn = xn - lambda * dx;            if norm(dx) < 1e-8                break;            end        end        x(:, n+1) = xn;    end    % ECG output    ECG = alpha * x;    % Plot    subplot(3,1,h_idx);    plot(t(:), ECG(:), 'k', 'LineWidth', 2.0);    xlim([25 40])    ylim([-1 1])    % Annotation and Labeling    title([titles{h_idx}]);    ylabel('ECG \xi(t)');    grid on;endxlabel('Time (s)');